//! Build-time codegen for `varps.json`: dump order kept (id order),
//! non-object rows skipped like the old reader.

/// Render `varps_generated.rs` from the parsed dump.
pub fn generate(manifest_dir: &str) {
    let parsed = crate::parse_dump(manifest_dir, "varps");
    let rows = crate::dump_rows(&parsed, "varps");
    let mut generated = String::from(
        "// Generated by rs/crates/gamedata/build.rs from gamedata/data/varps.json - do not edit.\n\
         pub static ALL: &[super::StaticVarp] = &[\n",
    );
    for row in rows {
        if !matches!(row, crate::workspace_json::Value::Obj(_)) {
            continue;
        }
        generated.push_str(&format!(
            "    super::StaticVarp {{ varp_id: {}, name: \"{}\", scope: {}, transmit: {} }},\n",
            row.get("id").as_i64().unwrap_or(-1),
            crate::escape_for_rust_literal(row.get("name").as_str().unwrap_or("")),
            row.get("scope").as_i64().unwrap_or(0),
            row.get("transmit").as_bool().unwrap_or(false),
        ));
    }
    generated.push_str("];\n");
    crate::emit_generated("varps_generated.rs", &generated);
}
